package com.rn_boilerplate_latest

import android.content.Context
import android.content.Intent
import android.content.IntentFilter
import android.os.BatteryManager
import android.os.Build
import com.facebook.react.bridge.Promise
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.fbreact.specs.NativeAppDeviceInfoSpec

/**
 * TurboModule Native Implementation for Android
 *
 * Implements the abstract NativeAppDeviceInfoSpec generated by React Native Codegen.
 * Notice: No @ReactMethod annotations needed; Codegen binds methods directly via JSI.
 */
class DeviceInfoModule(reactContext: ReactApplicationContext) : NativeAppDeviceInfoSpec(reactContext) {

    override fun getName(): String {
        return NAME
    }

    override fun getDeviceModel(): String {
        return "${Build.MANUFACTURER} ${Build.MODEL}"
    }

    override fun isEmulator(): Boolean {
        return (Build.FINGERPRINT.startsWith("generic")
                || Build.FINGERPRINT.startsWith("unknown")
                || Build.MODEL.contains("google_sdk")
                || Build.MODEL.contains("Emulator")
                || Build.MODEL.contains("Android SDK built for x86")
                || Build.MANUFACTURER.contains("Genymotion")
                || Build.PRODUCT.contains("sdk_google")
                || Build.PRODUCT.contains("google_sdk")
                || Build.HARDWARE.contains("goldfish")
                || Build.HARDWARE.contains("ranchu"))
    }

    override fun getBatteryLevel(promise: Promise) {
        try {
            val ifilter = IntentFilter(Intent.ACTION_BATTERY_CHANGED)
            val batteryStatus: Intent? = reactApplicationContext.registerReceiver(null, ifilter)
            val level: Int = batteryStatus?.getIntExtra(BatteryManager.EXTRA_LEVEL, -1) ?: -1
            val scale: Int = batteryStatus?.getIntExtra(BatteryManager.EXTRA_SCALE, -1) ?: -1

            val batteryPct = if (level != -1 && scale != -1) {
                ((level / scale.toFloat()) * 100).toInt()
            } else {
                -1
            }
            promise.resolve(batteryPct.toDouble())
        } catch (e: Exception) {
            promise.reject("BATTERY_ERROR", e.message, e)
        }
    }

    override fun getAppVersion(): String {
        return try {
            val pInfo = reactApplicationContext.packageManager.getPackageInfo(
                reactApplicationContext.packageName, 0
            )
            pInfo.versionName ?: "1.0.0"
        } catch (e: Exception) {
            "1.0.0"
        }
    }

    companion object {
        const val NAME = "NativeAppDeviceInfo"
    }
}
